/* Determines whether PDU is a request. */
#define COAP_PDU_IS_REQUEST(pdu) \
  (((pdu)->type == COAP_MESSAGE_CON) || ((pdu)->type == COAP_MESSAGE_NON))

coap_pdu_t *
coap_pdu_init(coap_pdu_type_t type, coap_pdu_code_t code, coap_mid_t mid,
              size_t size) {
  coap_pdu_t *pdu;

  pdu = coap_malloc_type(COAP_PDU, sizeof(coap_pdu_t));
  if (!pdu) {
    coap_log(LOG_CRIT, "coap_pdu_init: malloc\n");
    return NULL;
  }

  memset(pdu, 0, sizeof(coap_pdu_t));

  pdu->alloc_size = size;
  pdu->max_size = size;
  pdu->token_length = 0;
  pdu->max_opt = 0;
  pdu->code = code;
  pdu->type = type;
  pdu->mid = mid;

  pdu->data = (uint8_t *)coap_malloc_type(COAP_STRING, size);
  if (!pdu->data) {
    coap_log(LOG_CRIT, "coap_pdu_init: malloc data\n");
    coap_free_type(COAP_PDU, pdu);
    return NULL;
  }

  pdu->used_size = 0;
  pdu->hdr_size = 0;

  return pdu;
}

coap_pdu_t *
coap_new_pdu(void) {
  return coap_pdu_init(0, 0, 0, COAP_MAX_PDU_SIZE);
}

void
coap_delete_pdu(coap_pdu_t *pdu) {
  if (pdu) {
    if (pdu->data) {
      coap_free_type(COAP_STRING, pdu->data);
    }
    coap_free_type(COAP_PDU, pdu);
  }
}

size_t
coap_pdu_sizeof_header(const coap_pdu_t *pdu) {
  return pdu->hdr_size;
}

int
coap_pdu_set_code(coap_pdu_t *pdu, coap_pdu_code_t code) {
  if (pdu->used_size < 4) {
    return 0;
  }
  pdu->data[1] = code;
  pdu->code = code;
  return 1;
}

/* The functions below are used during parsing and encoding of PDUs. */

/**
 * Advances *optp to next option if possible. This function returns the number
 * of bytes that were consumed by the option value (i.e. without the option
 * header) or 0 on error. The option header is decoded and the result is stored
 * in @p result.
 */
size_t
coap_opt_parse(const uint8_t *data, size_t length, coap_opt_t *result) {
  size_t opt_length = 0;
  uint16_t delta, extended_delta = 0;
  uint16_t option_length, extended_length = 0;

  if (length < 1) {
    return 0;
  }

  delta = (data[0] & 0xF0) >> 4;
  option_length = data[0] & 0x0F;

  /* Check for extended delta and length */
  switch (delta) {
  case 13:
    if (length < 2) {
      return 0;
    }
    extended_delta = data[1] + 13;
    data++;
    length--;
    break;
  case 14:
    if (length < 3) {
      return 0;
    }
    extended_delta = (data[1] << 8) | data[2];
    extended_delta += 269;
    data += 2;
    length -= 2;
    break;
  case 15:
    /* reserved value */
    return 0;
  default:
    extended_delta = delta;
  }

  switch (option_length) {
  case 13:
    if (length < 2) {
      return 0;
    }
    extended_length = data[1] + 13;
    data++;
    length--;
    break;
  case 14:
    if (length < 3) {
      return 0;
    }
    extended_length = (data[1] << 8) | data[2];
    extended_length += 269;
    data += 2;
    length -= 2;
    break;
  case 15:
    /* reserved value */
    return 0;
  default:
    extended_length = option_length;
  }

  if (extended_length > length) {
    return 0;
  }

  *result = (coap_opt_t){.delta = extended_delta, .length = extended_length};

  /* Return the number of bytes consumed by the option value */
  return extended_length;
}
